-- Al Fatina's own words: the hero and the tagline already saved in the live database (they were
-- still Henine's slogan). The team can change them again in Admin → Page d'accueil.
UPDATE `settings` SET `value` = '{"eyebrow_fr":"La douceur au quotidien","eyebrow_ar":"الرقة في كل يوم","title_fr":"Belle, douce, et toujours vous","title_ar":"جميلة، ناعمة، وعلى طبيعتك دائمًا","subtitle_fr":"Des pièces tendres et élégantes, choisies pour que vous vous sentiez bien chaque jour, livrées avec soin partout en Algérie.","subtitle_ar":"قطع رقيقة وأنيقة اخترناها لتشعري بالراحة كل يوم، تصلك بعناية إلى كل أنحاء الجزائر."}' WHERE `key` = 'hero';--> statement-breakpoint
UPDATE `settings` SET `value` = replace(replace(replace(`value`, 'L’élégance & la qualité au meilleur prix', 'Belle, douce, et toujours vous'), 'L''élégance & la qualité au meilleur prix', 'Belle, douce, et toujours vous'), 'الأناقة والجودة بأفضل سعر', 'جميلة، ناعمة، وعلى طبيعتك دائمًا') WHERE `key` = 'store';--> statement-breakpoint
UPDATE `pages` SET `body_fr` = replace(`body_fr`, 'L’élégance & la qualité au meilleur prix', 'Belle, douce, et toujours vous'), `body_ar` = replace(`body_ar`, 'الأناقة والجودة بأفضل سعر', 'جميلة، ناعمة، وعلى طبيعتك دائمًا');
